/// Routes matched case by case, each calling a handler with what its patterns bind. F# compiles such a match to a
/// chain of tests, one case after another (each case calls the method pattern again), not to one decision tree: a
/// path that fails a case falls through to the next one.
module Routing.Wrapped.Shop

open Routing.Library.Web.Http
open Routing.Library.Web.Routing
open Routing.Library.Web.Tools

let route (request: HttpRequest) =
    match request with
    | GET([ "Products" ], _) -> Some(Handlers.list "products")
    | GET([ "Products"; Int32Str id ], _) -> Some(Handlers.show "products" id)
    | GET([ "Products"; Int32Str id; "Items"; Int32Str itemId ], _) -> Some(Handlers.item "products" id itemId)
    | POST([ "Products"; "New" ]) -> Some(Handlers.create "products")
    | POST([ "Products"; Int32Str id ]) -> Some(Handlers.update "products" id)
    | POST([ "Products"; Int32Str id; "Delete" ]) -> Some(Handlers.remove "products" id)
    | GET([ "Orders" ], _) -> Some(Handlers.list "orders")
    | GET([ "Orders"; Int32Str id ], _) -> Some(Handlers.show "orders" id)
    | GET([ "Orders"; Int32Str id; "Items"; Int32Str itemId ], _) -> Some(Handlers.item "orders" id itemId)
    | POST([ "Orders"; "New" ]) -> Some(Handlers.create "orders")
    | POST([ "Orders"; Int32Str id ]) -> Some(Handlers.update "orders" id)
    | POST([ "Orders"; Int32Str id; "Delete" ]) -> Some(Handlers.remove "orders" id)
    | GET([ "Customers" ], _) -> Some(Handlers.list "customers")
    | GET([ "Customers"; Int32Str id ], _) -> Some(Handlers.show "customers" id)
    | GET([ "Customers"; Int32Str id; "Items"; Int32Str itemId ], _) -> Some(Handlers.item "customers" id itemId)
    | POST([ "Customers"; "New" ]) -> Some(Handlers.create "customers")
    | POST([ "Customers"; Int32Str id ]) -> Some(Handlers.update "customers" id)
    | POST([ "Customers"; Int32Str id; "Delete" ]) -> Some(Handlers.remove "customers" id)
    | GET([ "Invoices" ], _) -> Some(Handlers.list "invoices")
    | GET([ "Invoices"; Int32Str id ], _) -> Some(Handlers.show "invoices" id)
    | GET([ "Invoices"; Int32Str id; "Items"; Int32Str itemId ], _) -> Some(Handlers.item "invoices" id itemId)
    | POST([ "Invoices"; "New" ]) -> Some(Handlers.create "invoices")
    | POST([ "Invoices"; Int32Str id ]) -> Some(Handlers.update "invoices" id)
    | POST([ "Invoices"; Int32Str id; "Delete" ]) -> Some(Handlers.remove "invoices" id)
    | GET([ "Carts" ], _) -> Some(Handlers.list "carts")
    | GET([ "Carts"; Int32Str id ], _) -> Some(Handlers.show "carts" id)
    | GET([ "Carts"; Int32Str id; "Items"; Int32Str itemId ], _) -> Some(Handlers.item "carts" id itemId)
    | POST([ "Carts"; "New" ]) -> Some(Handlers.create "carts")
    | POST([ "Carts"; Int32Str id ]) -> Some(Handlers.update "carts" id)
    | POST([ "Carts"; Int32Str id; "Delete" ]) -> Some(Handlers.remove "carts" id)
    | GET([ "Coupons" ], _) -> Some(Handlers.list "coupons")
    | GET([ "Coupons"; Int32Str id ], _) -> Some(Handlers.show "coupons" id)
    | GET([ "Coupons"; Int32Str id; "Items"; Int32Str itemId ], _) -> Some(Handlers.item "coupons" id itemId)
    | POST([ "Coupons"; "New" ]) -> Some(Handlers.create "coupons")
    | POST([ "Coupons"; Int32Str id ]) -> Some(Handlers.update "coupons" id)
    | POST([ "Coupons"; Int32Str id; "Delete" ]) -> Some(Handlers.remove "coupons" id)
    | GET([ "Reviews" ], _) -> Some(Handlers.list "reviews")
    | GET([ "Reviews"; Int32Str id ], _) -> Some(Handlers.show "reviews" id)
    | GET([ "Reviews"; Int32Str id; "Items"; Int32Str itemId ], _) -> Some(Handlers.item "reviews" id itemId)
    | POST([ "Reviews"; "New" ]) -> Some(Handlers.create "reviews")
    | POST([ "Reviews"; Int32Str id ]) -> Some(Handlers.update "reviews" id)
    | POST([ "Reviews"; Int32Str id; "Delete" ]) -> Some(Handlers.remove "reviews" id)
    | GET([ "Suppliers" ], _) -> Some(Handlers.list "suppliers")
    | GET([ "Suppliers"; Int32Str id ], _) -> Some(Handlers.show "suppliers" id)
    | GET([ "Suppliers"; Int32Str id; "Items"; Int32Str itemId ], _) -> Some(Handlers.item "suppliers" id itemId)
    | POST([ "Suppliers"; "New" ]) -> Some(Handlers.create "suppliers")
    | POST([ "Suppliers"; Int32Str id ]) -> Some(Handlers.update "suppliers" id)
    | POST([ "Suppliers"; Int32Str id; "Delete" ]) -> Some(Handlers.remove "suppliers" id)
    | GET([ "Shipments" ], _) -> Some(Handlers.list "shipments")
    | GET([ "Shipments"; Int32Str id ], _) -> Some(Handlers.show "shipments" id)
    | GET([ "Shipments"; Int32Str id; "Items"; Int32Str itemId ], _) -> Some(Handlers.item "shipments" id itemId)
    | POST([ "Shipments"; "New" ]) -> Some(Handlers.create "shipments")
    | POST([ "Shipments"; Int32Str id ]) -> Some(Handlers.update "shipments" id)
    | POST([ "Shipments"; Int32Str id; "Delete" ]) -> Some(Handlers.remove "shipments" id)
    | GET([ "Returns" ], _) -> Some(Handlers.list "returns")
    | GET([ "Returns"; Int32Str id ], _) -> Some(Handlers.show "returns" id)
    | GET([ "Returns"; Int32Str id; "Items"; Int32Str itemId ], _) -> Some(Handlers.item "returns" id itemId)
    | POST([ "Returns"; "New" ]) -> Some(Handlers.create "returns")
    | POST([ "Returns"; Int32Str id ]) -> Some(Handlers.update "returns" id)
    | POST([ "Returns"; Int32Str id; "Delete" ]) -> Some(Handlers.remove "returns" id)
    | _ -> None
